// frontend/src/utils/feeFilter.js
export const filterFeesByClass = (items, studentClass) => {
  const cls = Number(studentClass);
  const filtered = { ...items };

  if (cls >= 1 && cls <= 5) {
    // Primary classes (1–5): hide lab, sports, art/music fees
    ["labs", "sports", "artMusic", "dance", "art"].forEach(k => delete filtered[k]);
  } else if (cls >= 6 && cls <= 9) {
    // Middle classes (6–9): hide exam fee
    delete filtered["exam"];
  }
  // Classes 10–12: show all fees
  return filtered;
};
